<template><div class="state-panel" :class="[tone,{loading}]" role="status" aria-live="polite"><div v-if="loading" class="state-loader" aria-hidden="true"><i></i><i></i><span><ion-icon :icon="pulseOutline" /></span></div><span v-else class="state-icon"><ion-icon :icon="icon" /></span><strong>{{ title }}</strong><p>{{ message }}</p><ion-button v-if="retry&&!loading" fill="outline" size="small" @click="retry">Try again</ion-button></div></template>
<script setup lang="ts">import { computed } from 'vue';import { IonButton,IonIcon } from '@ionic/vue';import { alertCircleOutline,leafOutline,pulseOutline } from 'ionicons/icons';const props=defineProps<{loading?:boolean;title:string;message:string;retry?:()=>void;tone?:'neutral'|'danger'}>();const icon=computed(()=>props.tone==='danger'?alertCircleOutline:leafOutline);</script>